/* GreenBean Coffee — Shared Styles */

:root {
  --gb-green: #00824A;
  --gb-green-dark: #006B3C;
  --gb-forest: #32462F;
  --gb-cream: #F3CEA1;
  --gb-cream-soft: #FBF3E7;
  --gb-cream-paper: #FAF6EE;
  --gb-bean: #2C1810;
  --gb-coffee: #6B4226;
  --gb-mocha: #8B5A3C;
  --gb-stone: #E8DCC4;
  --gb-ink: #1A1A1A;
  --gb-text: #2A2A2A;
  --gb-mute: #6F6F6F;
  --gb-border: #E5DECF;
  --gb-white: #FFFFFF;
  --gb-star: #D4A24C;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: 'DM Sans', system-ui, -apple-system, sans-serif;
  background: var(--gb-cream-paper);
  color: var(--gb-text);
  line-height: 1.55;
  font-size: 16px;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5 {
  font-family: 'Fraunces', Georgia, serif;
  color: var(--gb-forest);
  letter-spacing: -0.01em;
  line-height: 1.1;
  font-weight: 600;
}

a { color: inherit; text-decoration: none; }

img { max-width: 100%; display: block; }

button { font-family: inherit; cursor: pointer; border: none; background: none; }

.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.container-wide {
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ============ HEADER ============ */
.gb-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gb-border);
}
.gb-header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 32px;
  max-width: 1440px;
  margin: 0 auto;
}
.gb-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: 'Fraunces', serif;
  font-weight: 700;
  font-size: 20px;
  color: var(--gb-forest);
}
.gb-logo-mark {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: var(--gb-green);
  display: grid;
  place-items: center;
  color: var(--gb-cream);
  flex-shrink: 0;
}
.gb-nav { display: flex; align-items: center; gap: 32px; }
.gb-nav a {
  font-size: 15px;
  font-weight: 500;
  color: var(--gb-forest);
  position: relative;
  padding: 8px 0;
  transition: color .2s ease;
}
.gb-nav a:hover { color: var(--gb-green); }
.gb-nav a.active::after {
  content: '';
  position: absolute;
  bottom: -2px; left: 0; right: 0;
  height: 2px;
  background: var(--gb-green);
  border-radius: 2px;
}
.gb-actions { display: flex; align-items: center; gap: 12px; }
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 22px;
  border-radius: 999px;
  font-weight: 600;
  font-size: 14px;
  transition: all .2s ease;
  cursor: pointer;
  white-space: nowrap;
  border: 1.5px solid transparent;
}
.btn-primary { background: var(--gb-forest); color: var(--gb-cream-soft); }
.btn-primary:hover { background: var(--gb-green); transform: translateY(-1px); }
.btn-outline { background: transparent; color: var(--gb-forest); border-color: var(--gb-forest); }
.btn-outline:hover { background: var(--gb-forest); color: var(--gb-cream-soft); }
.btn-green { background: var(--gb-green); color: white; }
.btn-green:hover { background: var(--gb-green-dark); transform: translateY(-1px); }
.btn-ghost { background: transparent; color: var(--gb-forest); }
.btn-ghost:hover { background: var(--gb-cream-soft); }
.btn-cream { background: var(--gb-cream); color: var(--gb-forest); }
.btn-cream:hover { background: #ecbf8c; }

.gb-mobile-toggle { display: none; }

/* ============ FOOTER ============ */
.gb-footer {
  background: var(--gb-forest);
  color: var(--gb-cream-soft);
  padding: 80px 0 40px;
  margin-top: 80px;
}
.gb-footer-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 40px;
  margin-bottom: 60px;
}
.gb-footer h4 {
  color: var(--gb-cream);
  font-family: 'DM Sans', sans-serif;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-bottom: 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: default;
}
.gb-footer ul { list-style: none; }
.gb-footer ul li { margin-bottom: 12px; }
.gb-footer ul a {
  color: rgba(251, 243, 231, 0.78);
  font-size: 14px;
  transition: color .2s;
}
.gb-footer ul a:hover { color: var(--gb-cream); text-decoration: underline; }
.gb-footer-bottom {
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
  justify-content: space-between;
  padding-top: 32px;
  border-top: 1px solid rgba(243, 206, 161, 0.18);
  font-size: 13px;
  color: rgba(251, 243, 231, 0.6);
}
.gb-footer-bottom .gb-fb-links { display: flex; gap: 24px; flex-wrap: wrap; }
.gb-footer h4 .chev { display: none; }

/* ============ COOKIE BANNER ============ */
.gb-cookie {
  position: fixed;
  bottom: 24px;
  left: 24px;
  right: 24px;
  max-width: 1100px;
  margin: 0 auto;
  background: var(--gb-forest);
  color: var(--gb-cream-soft);
  border-radius: 18px;
  padding: 20px 28px;
  display: flex;
  align-items: center;
  gap: 28px;
  box-shadow: 0 18px 48px rgba(0,0,0,.18);
  z-index: 200;
  animation: cookieIn .5s ease both;
}
@keyframes cookieIn { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0);} }
.gb-cookie-text { flex: 1; }
.gb-cookie h5 {
  font-family: 'Fraunces', serif;
  font-size: 17px;
  color: var(--gb-cream);
  margin-bottom: 4px;
}
.gb-cookie p { font-size: 13.5px; color: rgba(251, 243, 231, 0.78); }
.gb-cookie-actions { display: flex; gap: 10px; flex-shrink: 0; }
.gb-cookie.hidden { display: none; }

/* ============ HERO ============ */
.hero {
  position: relative;
  background: linear-gradient(135deg, #006B3C 0%, #00824A 60%, #00A85F 100%);
  color: white;
  padding: 100px 0 120px;
  overflow: hidden;
}
.hero-bg {
  position: absolute;
  inset: 0;
  opacity: 0.08;
  background-image:
    radial-gradient(circle at 20% 30%, var(--gb-cream) 1px, transparent 1px),
    radial-gradient(circle at 70% 80%, var(--gb-cream) 1px, transparent 1px);
  background-size: 60px 60px, 80px 80px;
}
.hero-grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 60px;
  align-items: center;
  position: relative;
  z-index: 1;
}
.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(243, 206, 161, 0.18);
  border: 1px solid rgba(243, 206, 161, 0.4);
  color: var(--gb-cream);
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 500;
  margin-bottom: 24px;
}
.hero h1 {
  font-size: clamp(48px, 7vw, 92px);
  color: var(--gb-cream);
  font-weight: 600;
  letter-spacing: -0.025em;
  margin-bottom: 24px;
}
.hero h1 em {
  font-style: italic;
  font-weight: 400;
  color: #FCDCB4;
}
.hero-sub {
  font-size: 19px;
  color: rgba(251, 243, 231, 0.88);
  margin-bottom: 36px;
  max-width: 520px;
}
.hero-ctas { display: flex; gap: 14px; flex-wrap: wrap; }
.hero .btn-primary { background: var(--gb-cream); color: var(--gb-forest); padding: 16px 32px; font-size: 15px; }
.hero .btn-primary:hover { background: white; }
.hero .btn-outline { color: var(--gb-cream); border-color: rgba(243, 206, 161, 0.55); padding: 16px 28px; }
.hero .btn-outline:hover { background: rgba(243, 206, 161, 0.12); color: white; }

.hero-visual {
  position: relative;
  height: 480px;
}
.cup-illustration {
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  position: relative;
}
.cup-circle {
  width: 380px;
  height: 380px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, #FCDCB4 0%, var(--gb-cream) 50%, #E2B782 100%);
  position: relative;
  box-shadow: 0 30px 80px rgba(0,0,0,0.25), inset -20px -30px 60px rgba(139, 90, 60, 0.25);
  display: grid;
  place-items: center;
}
.cup-circle::before {
  content: '';
  position: absolute;
  inset: 32px;
  border-radius: 50%;
  background: radial-gradient(circle at 50% 40%, #6B4226 0%, #4A2E1A 60%, #2C1810 100%);
  box-shadow: inset 0 8px 30px rgba(0,0,0,0.4);
}
.cup-circle::after {
  content: '';
  position: absolute;
  width: 110px;
  height: 110px;
  border-radius: 50%;
  background: radial-gradient(circle, #C8A878 0%, transparent 70%);
  opacity: 0.85;
  z-index: 1;
  top: 38%;
  left: 38%;
  transform: rotate(15deg);
}
.steam {
  position: absolute;
  width: 100%;
  top: -40px;
  display: flex;
  justify-content: center;
  gap: 36px;
  pointer-events: none;
}
.steam span {
  display: block;
  width: 5px;
  height: 60px;
  background: linear-gradient(to top, rgba(251, 243, 231, 0.5), transparent);
  border-radius: 3px;
  animation: steamRise 3s ease-in-out infinite;
}
.steam span:nth-child(2) { animation-delay: .5s; height: 80px; }
.steam span:nth-child(3) { animation-delay: 1s; }
@keyframes steamRise {
  0%, 100% { transform: translateY(0) scale(1); opacity: .7; }
  50% { transform: translateY(-15px) scale(1.1); opacity: 1; }
}
.floating-bean {
  position: absolute;
  width: 60px; height: 80px;
  background: var(--gb-bean);
  border-radius: 50%;
  box-shadow: 0 12px 30px rgba(0,0,0,0.3);
  animation: float 6s ease-in-out infinite;
}
.floating-bean::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: linear-gradient(45deg, transparent 48%, var(--gb-coffee) 49%, var(--gb-coffee) 51%, transparent 52%);
}
.floating-bean.b1 { top: 8%; right: 12%; animation-delay: 0s; transform: rotate(-25deg); width: 50px; height: 68px; }
.floating-bean.b2 { bottom: 10%; left: 6%; animation-delay: 1.5s; transform: rotate(35deg); width: 70px; height: 92px; }
.floating-bean.b3 { bottom: 25%; right: 4%; animation-delay: 3s; transform: rotate(15deg); width: 44px; height: 60px; }
@keyframes float {
  0%, 100% { transform: translateY(0) rotate(var(--r, 0deg)); }
  50% { transform: translateY(-20px) rotate(var(--r, 0deg)); }
}

/* ============ SECTIONS ============ */
.section { padding: 100px 0; }
.section-tight { padding: 60px 0; }
.section h2 {
  font-size: clamp(34px, 4.5vw, 56px);
  margin-bottom: 16px;
  font-weight: 500;
}
.section-eyebrow {
  display: inline-block;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--gb-green);
  margin-bottom: 14px;
}

/* Featured Product band */
.feature-band {
  background: var(--gb-cream-soft);
  padding: 80px 0;
}
.feature-band .grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}
.feature-band h2 { color: var(--gb-forest); font-size: clamp(32px, 4vw, 48px); }
.feature-band p { color: var(--gb-text); font-size: 17px; margin: 18px 0 28px; max-width: 480px; }
.feature-visual {
  border-radius: 32px;
  height: 460px;
  position: relative;
  overflow: hidden;
}
.feature-visual.citrus {
  background: linear-gradient(135deg, #FFB957 0%, #FF6B35 50%, #E84B1A 100%);
}
.feature-visual.afternoon {
  background: linear-gradient(135deg, #C0875F 0%, #8B5A3C 60%, #5A3924 100%);
}
.feature-visual.fruity {
  background: linear-gradient(135deg, #FFB199 0%, #FF7A8E 60%, #B45A8A 100%);
}
.feature-visual.spring {
  background: linear-gradient(135deg, #B19CD9 0%, #9B7ECC 50%, #6B4F9E 100%);
}
.feature-visual.nondairy {
  background: linear-gradient(135deg, #F5E5C7 0%, #E2B782 60%, #C0875F 100%);
}
.feature-visual .blob {
  position: absolute;
  border-radius: 50%;
  filter: blur(40px);
  opacity: 0.55;
}
.feature-visual .b1 { width: 200px; height: 200px; background: white; top: -40px; right: -30px; }
.feature-visual .b2 { width: 180px; height: 180px; background: rgba(255,255,255,0.4); bottom: 30px; left: 40px; }
.feature-visual .glass-cup {
  position: absolute;
  bottom: 50px;
  left: 50%;
  transform: translateX(-50%);
  width: 200px;
  height: 280px;
  background: rgba(255, 255, 255, 0.15);
  border: 2px solid rgba(255, 255, 255, 0.45);
  border-radius: 18px 18px 36px 36px;
  backdrop-filter: blur(8px);
  overflow: hidden;
}
.feature-visual .glass-cup::before {
  content: '';
  position: absolute;
  inset: 8px 8px 8px 8px;
  background: linear-gradient(to top, rgba(255,255,255,0.3) 0%, rgba(255,255,255,0.1) 100%);
  border-radius: 12px 12px 28px 28px;
}
.feature-visual .glass-cup::after {
  content: '';
  position: absolute;
  top: 18px;
  left: 18px;
  right: 18px;
  height: 70%;
  background: linear-gradient(to bottom, rgba(255,255,255,0.6) 0%, rgba(255,255,255,0.2) 30%, transparent 70%);
  border-radius: 8px;
  filter: blur(2px);
}
.feature-visual .label {
  position: absolute;
  top: 24px;
  left: 24px;
  background: white;
  color: var(--gb-forest);
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  z-index: 2;
}

.feature-band.reverse .grid { grid-template-columns: 1fr 1fr; }
.feature-band.reverse .feature-visual { order: -1; }

/* Two-up promo */
.two-up {
  background: var(--gb-cream-paper);
  padding: 80px 0;
}
.two-up .grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
}
.promo-card {
  border-radius: 28px;
  padding: 56px 48px;
  position: relative;
  overflow: hidden;
  min-height: 420px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  color: white;
  isolation: isolate;
}
.promo-card.ai {
  background: linear-gradient(135deg, #32462F 0%, #00824A 100%);
}
.promo-card.nondairy-card {
  background: linear-gradient(135deg, #6B4226 0%, #8B5A3C 50%, #C0875F 100%);
}
.promo-card h3 {
  font-size: clamp(26px, 3vw, 38px);
  color: var(--gb-cream);
  margin-bottom: 14px;
  position: relative;
  z-index: 1;
}
.promo-card p {
  color: rgba(251, 243, 231, 0.88);
  margin-bottom: 28px;
  font-size: 16px;
  max-width: 420px;
  position: relative;
  z-index: 1;
}
.promo-card .deco {
  position: absolute;
  inset: 0;
  opacity: 0.18;
  z-index: 0;
}
.promo-card .deco svg { width: 100%; height: 100%; }
.promo-card .btn { align-self: flex-start; position: relative; z-index: 1; }
.promo-card .btn-cream { background: var(--gb-cream); color: var(--gb-forest); }
.promo-card .btn-cream:hover { background: white; }

/* ============ Page intro ============ */
.page-intro {
  background: linear-gradient(180deg, var(--gb-cream-soft) 0%, var(--gb-cream-paper) 100%);
  padding: 60px 0 50px;
  border-bottom: 1px solid var(--gb-border);
}
.breadcrumb {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  color: var(--gb-mute);
  margin-bottom: 20px;
}
.breadcrumb a:hover { color: var(--gb-green); }
.breadcrumb .sep { opacity: .5; }
.page-intro h1 {
  font-size: clamp(38px, 5vw, 64px);
  color: var(--gb-forest);
  margin-bottom: 12px;
}
.page-intro p { font-size: 17px; color: var(--gb-mute); max-width: 640px; }

/* Mobile */
@media (max-width: 1024px) {
  .gb-footer-grid { grid-template-columns: repeat(2, 1fr); gap: 32px; }
}
@media (max-width: 860px) {
  .gb-nav, .gb-actions .btn-outline { display: none; }
  .gb-mobile-toggle {
    display: grid; place-items: center;
    width: 42px; height: 42px;
    border-radius: 12px;
    background: var(--gb-cream-soft);
    color: var(--gb-forest);
  }
  .hero { padding: 60px 0 80px; }
  .hero-grid { grid-template-columns: 1fr; gap: 32px; }
  .hero-visual { height: 320px; }
  .cup-circle { width: 260px; height: 260px; }
  .feature-band .grid, .two-up .grid { grid-template-columns: 1fr; gap: 32px; }
  .feature-band.reverse .feature-visual { order: 0; }
  .feature-visual { height: 320px; }
  .section { padding: 60px 0; }
  .gb-footer { padding: 60px 0 30px; }
  .gb-footer-grid { grid-template-columns: 1fr; gap: 0; margin-bottom: 32px; }
  .gb-footer h4 {
    cursor: pointer;
    padding: 18px 0;
    border-bottom: 1px solid rgba(243, 206, 161, 0.15);
    margin-bottom: 0;
  }
  .gb-footer h4 .chev {
    display: inline-block;
    transition: transform .25s ease;
  }
  .gb-footer-col.open h4 .chev { transform: rotate(180deg); }
  .gb-footer-col ul {
    max-height: 0;
    overflow: hidden;
    transition: max-height .35s ease;
  }
  .gb-footer-col.open ul {
    max-height: 500px;
    padding: 12px 0 18px;
  }
  .gb-cookie { flex-direction: column; align-items: stretch; gap: 16px; padding: 18px; }
  .gb-cookie-actions { flex-direction: row; }
  .gb-cookie-actions .btn { flex: 1; }
  .promo-card { padding: 40px 28px; min-height: 340px; }
}
@media (max-width: 480px) {
  .gb-header-inner { padding: 14px 18px; }
  .gb-logo { font-size: 17px; }
  .gb-actions .btn { padding: 10px 14px; font-size: 13px; }
  .container, .container-wide { padding: 0 18px; }
  .hero h1 { font-size: 42px; }
  .hero-sub { font-size: 16px; }
}

/* GreenBean Coffee — Shared Styles */

:root {
  --gb-green: #00824A;
  --gb-green-dark: #006B3C;
  --gb-forest: #32462F;
  --gb-cream: #F3CEA1;
  --gb-cream-soft: #FBF3E7;
  --gb-cream-paper: #FAF6EE;
  --gb-bean: #2C1810;
  --gb-coffee: #6B4226;
  --gb-mocha: #8B5A3C;
  --gb-stone: #E8DCC4;
  --gb-ink: #1A1A1A;
  --gb-text: #2A2A2A;
  --gb-mute: #6F6F6F;
  --gb-border: #E5DECF;
  --gb-white: #FFFFFF;
  --gb-star: #D4A24C;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: 'DM Sans', system-ui, -apple-system, sans-serif;
  background: var(--gb-cream-paper);
  color: var(--gb-text);
  line-height: 1.55;
  font-size: 16px;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5 {
  font-family: 'Fraunces', Georgia, serif;
  color: var(--gb-forest);
  letter-spacing: -0.01em;
  line-height: 1.1;
  font-weight: 600;
}

a { color: inherit; text-decoration: none; }

img { max-width: 100%; display: block; }

button { font-family: inherit; cursor: pointer; border: none; background: none; }

.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.container-wide {
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ============ HEADER ============ */
.gb-header {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gb-border);
