  gap: 8px;
  background: rgba(243, 206, 161, 0.18);
  border: 1px solid rgba(243, 206, 161, 0.4);
  color: var(--gb-cream);
  padding: 8px 16px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 500;
  margin-bottom: 24px;
}
.hero h1 {
