}
.cup-circle::after {
  content: '';
  position: absolute;
  width: 110px;
  height: 110px;
  border-radius: 50%;
  background: radial-gradient(circle, #C8A878 0%, transparent 70%);
  opacity: 0.85;
  z-index: 1;
  top: 38%;
  left: 38%;
  transform: rotate(15deg);
}
.steam {
  position: absolute;
  width: 100%;
  top: -40px;
  display: flex;
  justify-content: center;
  gap: 36px;
  pointer-events: none;
}
.steam span {
  display: block;
