      transition: transform .2s, box-shadow .2s;
      cursor: pointer;
    }
    .gift-card:hover { transform: translateY(-4px); box-shadow: 0 12px 36px rgba(0,0,0,.1); }
    .gift-card-img {
      height: 152px;
      display: grid; place-items: center;
      position: relative;
