    .carousel-btn {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 44px; height: 44px;
      border-radius: 50%;
      background: white;
      box-shadow: 0 4px 16px rgba(0,0,0,.12);
      border: 1px solid var(--gb-border);
      display: grid; place-items: center;
      cursor: pointer;
      z-index: 5;
      transition: all .2s;
      color: var(--gb-forest);
    }
    .carousel-btn:hover { background: var(--gb-green); color: white; border-color: var(--gb-green); }
    .carousel-btn.prev { left: -18px; }
    .carousel-btn.next { right: -18px; }

    /* Category Section */
    .cat-section { padding: 48px 0; border-top: 1px solid var(--gb-border); }
    .cat-section:first-of-type { border-top: none; }
    .cat-header { display: flex; align-items: center; gap: 12px; margin-bottom: 20px; }
    .cat-icon {
      width: 40px; height: 40px; border-radius: 12px;
      display: grid; place-items: center;
    }
    .cat-header h3 { font-size: 22px; font-weight: 500; }

    /* Business Gifting */
    .biz-section {
      padding: 80px 0; background: var(--gb-cream-soft);
      margin-top: 40px;
    }
    .biz-grid {
      display: grid; grid-template-columns: 1fr 1fr;
      gap: 60px; align-items: center;
    }
    .biz-visual {
      border-radius: 28px;
      height: 400px;
      background: linear-gradient(135deg, var(--gb-forest) 0%, var(--gb-green) 100%);
      display: grid; place-items: center;
      position: relative; overflow: hidden;
    }
    .biz-visual .biz-deco {
      position: absolute;
      width: 200px; height: 140px;
      border-radius: 16px;
      background: rgba(243,206,161,.2);
      border: 2px solid rgba(243,206,161,.4);
      transform: rotate(-6deg);
    }
    .biz-visual .bd1 { top: 60px; left: 40px; }
    .biz-visual .bd2 { top: 100px; left: 80px; transform: rotate(3deg); background: rgba(243,206,161,.12); }
    .biz-visual .bd3 { top: 80px; left: 60px; transform: rotate(-2deg); background: rgba(255,255,255,.08); border-color: rgba(255,255,255,.3); }
    .biz-text h2 { font-size: clamp(28px,3.5vw,42px); margin-bottom: 16px; }
    .biz-text p { color: var(--gb-mute); font-size: 16px; margin-bottom: 28px; max-width: 460px; }

    /* eGift Info */
    .egift-section { padding: 80px 0; text-align: center; }
    .egift-cards {
      display: grid; grid-template-columns: repeat(3, 1fr);
      gap: 24px; margin-top: 40px; max-width: 840px; margin-left: auto; margin-right: auto;
    }
    .egift-card {
      background: white; border-radius: 20px; padding: 32px 24px;
      box-shadow: 0 4px 20px rgba(0,0,0,.04); border: 1px solid var(--gb-border);
      text-align: center;
    }
    .egift-card-icon {
      width: 52px; height: 52px; border-radius: 16px;
      display: grid; place-items: center; margin: 0 auto 16px;
    }
    .egift-card h4 {
      font-family: 'DM Sans', sans-serif;
      font-size: 15px; font-weight: 600; color: var(--gb-forest);
      margin-bottom: 6px;
    }
    .egift-card p { font-size: 13.5px; color: var(--gb-mute); }

    /* FAQ */
    .faq-section { padding: 80px 0; background: var(--gb-cream-soft); }
    .faq-list { max-width: 720px; margin: 32px auto 0; }
    .faq-item { border-bottom: 1px solid var(--gb-border); }
    .faq-q {
      display: flex; justify-content: space-between; align-items: center;
      padding: 20px 0; cursor: pointer; font-weight: 600; font-size: 15.5px;
      color: var(--gb-text); width: 100%; text-align: left;
    }
    .faq-q .faq-chev { transition: transform .25s; font-size: 18px; color: var(--gb-mute); }
    .faq-a {
      max-height: 0; overflow: hidden; transition: max-height .3s ease;
      color: var(--gb-mute); font-size: 14.5px; line-height: 1.6;
    }
    .faq-item.open .faq-a { max-height: 200px; padding-bottom: 20px; }
    .faq-item.open .faq-chev { transform: rotate(180deg); }

    @media (max-width: 860px) {
      .gift-hero { padding: 60px 0 80px; }
      .biz-grid { grid-template-columns: 1fr; gap: 32px; }
      .biz-visual { height: 280px; }
      .egift-cards { grid-template-columns: 1fr; max-width: 360px; }
      .gift-card { flex: 0 0 200px; }
      .carousel-btn { display: none; }
    }
