  <script>
    function toggleMobileNav() { const m = document.getElementById('mobileMenu'); m.style.display = m.style.display === 'none' ? 'block' : 'none'; }
    document.querySelectorAll('.gb-footer-col h4').forEach(h => { h.addEventListener('click', () => { if (window.innerWidth <= 860) h.parentElement.classList.toggle('open'); }); });

    // Search suggestions
    const searchInput = document.getElementById('storeSearch');
    const suggestionsEl = document.getElementById('suggestions');
    searchInput.addEventListener('input', function() {
      if (this.value.length > 0) {
        suggestionsEl.classList.add('show');
      } else {
        suggestionsEl.classList.remove('show');
      }
    });
    searchInput.addEventListener('focus', function() {
      if (this.value.length > 0) suggestionsEl.classList.add('show');
    });
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.search-input-wrap')) suggestionsEl.classList.remove('show');
    });
    function selectSuggestion(el) {
      searchInput.value = el.textContent.trim();
      suggestionsEl.classList.remove('show');
    }

    // Filter toggle
    function toggleFilter() {
      const panel = document.getElementById('filterPanel');
      const btn = document.getElementById('filterBtn');
      panel.classList.toggle('open');
      btn.classList.toggle('active');
    }

    // Order type toggle
    function switchOrderType(btn) {
      btn.parentElement.querySelectorAll('button').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
    }

    // Store card selection
    document.querySelectorAll('.store-card').forEach(card => {
      card.addEventListener('click', function(e) {
        if (e.target.closest('.btn')) return;
        document.querySelectorAll('.store-card').forEach(c => c.classList.remove('selected'));
        this.classList.add('selected');
      });
    });
  </script>
